content:
A \textbf{function} $f$ from a set $A$ to a set $B$ is a rule that assigns to each element $x$ in $A$ exactly one element $y$ in $B$. We write:
\[
f: A \to B \quad \text{or} \quad y = f(x)
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Key Points:}}
\begin{itemize}
    \item $x$ is called the \textbf{independent variable} or \textbf{input}
    \item $y$ is called the \textbf{dependent variable} or \textbf{output}
    \item The set $A$ is called the \textbf{domain} of $f$
    \item The set of all possible outputs is called the \textbf{range} of $f$
    \item Each input must produce exactly ONE output (uniqueness)
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Determine which of the following relations are functions:

(a) $f(x) = x^2 + 1$

(b) $x^2 + y^2 = 25$ (circle equation)

(c) $g(t) = \sqrt{t - 1}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} For $f(x) = x^2 + 1$:

For any value of $x$, we compute $x^2$, then add 1. This gives exactly one output.
\begin{align*}
x = 2 &\implies f(2) = 2^2 + 1 = 5 \\
x = -3 &\implies f(-3) = (-3)^2 + 1 = 10
\end{align*}

\textcolor{green}{\checkmark} \textbf{This IS a function.}

\vspace{0.3cm}
\textbf{(b)} For $x^2 + y^2 = 25$:

If $x = 0$, then $y^2 = 25$, which gives $y = 5$ or $y = -5$ (two outputs!).

\textcolor{red}{$\times$} \textbf{This is NOT a function} because one input produces multiple outputs.

\vspace{0.3cm}
\textbf{(c)} For $g(t) = \sqrt{t - 1}$:

For any valid $t$, the square root produces exactly one non-negative value.
\[
t = 5 \implies g(5) = \sqrt{5-1} = \sqrt{4} = 2
\]

\textcolor{green}{\checkmark} \textbf{This IS a function.}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} The domain is $t \geq 1$ (we cannot take square root of negative numbers in real numbers).

\vspace{0.5cm}

For a function $f: A \to B$:

\textbf{Domain:} The set of all permissible input values for which the function is defined.
\[
\text{Domain}(f) = \{x : f(x) \text{ exists}\}
\]

\textbf{Range:} The set of all actual output values produced by the function.
\[
\text{Range}(f) = \{y : y = f(x) \text{ for some } x \in \text{Domain}(f)\}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Common Domain Restrictions:}}
\begin{itemize}
    \item \textbf{Division:} Cannot divide by zero $\implies$ exclude values where denominator = 0
    \item \textbf{Square roots:} Expression under $\sqrt{\phantom{x}}$ must be non-negative (for real functions)
    \item \textbf{Logarithms:} Argument of $\ln(x)$ or $\log(x)$ must be positive
\end{itemize}

\vspace{0.5cm}

A function $f$ is called:

\textbf{Even} if $f(-x) = f(x)$ for all $x$ in the domain.
\begin{itemize}
    \item Graph is symmetric about the $y$-axis
    \item Example: $f(x) = x^2$, $f(x) = \cos x$
\end{itemize}

\textbf{Odd} if $f(-x) = -f(x)$ for all $x$ in the domain.
\begin{itemize}
    \item Graph is symmetric about the origin
    \item Example: $f(x) = x^3$, $f(x) = \sin x$
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} A function can be neither even nor odd!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Determine whether the following functions are even, odd, or neither:

(a) $f(x) = x^5 + x$

(b) $g(x) = x^4 - 2x^2 + 1$

(c) $h(x) = x^3 + x^2$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} For $f(x) = x^5 + x$:

Compute $f(-x)$:
\begin{align*}
f(-x) &= (-x)^5 + (-x) \\
&= -x^5 - x \\
&= -(x^5 + x) \\
&= -f(x)
\end{align*}

Since $f(-x) = -f(x)$, the function is \textbf{ODD}. \textcolor{green}{\checkmark}

\vspace{0.3cm}
\textbf{(b)} For $g(x) = x^4 - 2x^2 + 1$:

Compute $g(-x)$:
\begin{align*}
g(-x) &= (-x)^4 - 2(-x)^2 + 1 \\
&= x^4 - 2x^2 + 1 \\
&= g(x)
\end{align*}

Since $g(-x) = g(x)$, the function is \textbf{EVEN}. \textcolor{green}{\checkmark}

\vspace{0.3cm}
\textbf{(c)} For $h(x) = x^3 + x^2$:

Compute $h(-x)$:
\begin{align*}
h(-x) &= (-x)^3 + (-x)^2 \\
&= -x^3 + x^2
\end{align*}

Now check:
\begin{itemize}
    \item Is $h(-x) = h(x)$? Compare $-x^3 + x^2$ with $x^3 + x^2$ \textcolor{red}{$\times$} No
    \item Is $h(-x) = -h(x)$? Compare $-x^3 + x^2$ with $-(x^3 + x^2) = -x^3 - x^2$ \textcolor{red}{$\times$} No
\end{itemize}

The function is \textbf{NEITHER even nor odd}.

\vspace{0.5cm}

A function $f$ has an \textbf{inverse function} $f^{-1}$ if there exists a function $f^{-1}$ such that:
\[
f^{-1}(f(x)) = x \quad \text{for all } x \text{ in domain of } f
\]
\[
f(f^{-1}(y)) = y \quad \text{for all } y \text{ in domain of } f^{-1}
\]

\textcolor{primaryblue}{\faInfoCircle\ \textbf{Key Properties:}}
\begin{itemize}
    \item A function has an inverse if and only if it is \textbf{one-to-one} (each output corresponds to exactly one input)
    \item The graph of $f^{-1}$ is the reflection of the graph of $f$ across the line $y = x$
    \item Domain of $f^{-1}$ = Range of $f$
    \item Range of $f^{-1}$ = Domain of $f$
\end{itemize}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Warning:}} $f^{-1}(x) \neq \dfrac{1}{f(x)}$ ! The notation means inverse, not reciprocal.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Find the inverse function $f^{-1}(x)$ for:

(a) $f(x) = 2x + 3$

(b) $f(x) = x^3 + 1$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} For $f(x) = 2x + 3$:

\textbf{Step 1:} Write $y = f(x)$
\[
y = 2x + 3
\]

\textbf{Step 2:} Solve for $x$ in terms of $y$
\begin{align*}
y &= 2x + 3 \\
y - 3 &= 2x \\
x &= \frac{y - 3}{2}
\end{align*}

\textbf{Step 3:} Replace $y$ with $x$ to get $f^{-1}(x)$
\[
f^{-1}(x) = \frac{x - 3}{2}
\]

\textbf{Verification:} Check that $f(f^{-1}(x)) = x$
\begin{align*}
f(f^{-1}(x)) &= f\left(\frac{x-3}{2}\right) \\
&= 2\left(\frac{x-3}{2}\right) + 3 \\
&= x - 3 + 3 \\
&= x \quad \textcolor{green}{\checkmark}
\end{align*}

\textbf{Answer:} \boxed{f^{-1}(x) = \frac{x-3}{2}}

\vspace{0.3cm}
\textbf{(b)} For $f(x) = x^3 + 1$:

\textbf{Step 1:} Write $y = f(x)$
\[
y = x^3 + 1
\]

\textbf{Step 2:} Solve for $x$ in terms of $y$
\begin{align*}
y &= x^3 + 1 \\
y - 1 &= x^3 \\
x &= \sqrt[3]{y - 1}
\end{align*}

\textbf{Step 3:} Replace $y$ with $x$
\[
f^{-1}(x) = \sqrt[3]{x - 1}
\]

\textbf{Verification:}
\begin{align*}
f(f^{-1}(x)) &= f(\sqrt[3]{x-1}) \\
&= (\sqrt[3]{x-1})^3 + 1 \\
&= x - 1 + 1 \\
&= x \quad \textcolor{green}{\checkmark}
\end{align*}

\textbf{Answer:} \boxed{f^{-1}(x) = \sqrt[3]{x-1}}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Consider the function:
\[
f(x) = \frac{x^2 - 4}{x - 2}
\]

(a) What is $f(2)$?

(b) What is $\displaystyle\lim_{x \to 2} f(x)$?

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Finding $f(2)$:

Direct substitution:
\[
f(2) = \frac{2^2 - 4}{2 - 2} = \frac{0}{0}
\]

This is \textbf{undefined}! So $f(2)$ does not exist.

\vspace{0.3cm}
\textbf{(b)} Finding $\displaystyle\lim_{x \to 2} f(x)$:

Even though $f(2)$ doesn't exist, we can examine what happens as $x$ gets close to 2.

First, simplify the function:
\begin{align*}
f(x) &= \frac{x^2 - 4}{x - 2} \\
&= \frac{(x-2)(x+2)}{x - 2} \\
&= x + 2 \quad \text{(for } x \neq 2\text{)}
\end{align*}

Now create a table of values approaching $x = 2$:

\begin{center}
\begin{tabular}{|c|c||c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ (from left) & $f(x) = x+2$ & $x$ (from right) & $f(x) = x+2$ \\
\hline
1.9 & 3.9 & 2.1 & 4.1 \\
\hline
1.99 & 3.99 & 2.01 & 4.01 \\
\hline
1.999 & 3.999 & 2.001 & 4.001 \\
\hline
1.9999 & 3.9999 & 2.0001 & 4.0001 \\
\hline
\end{tabular}
\end{center}

\textcolor{green}{\textbf{Observation:}} As $x$ approaches 2 from either side, $f(x)$ approaches 4.

\textbf{Answer:} $\displaystyle\lim_{x \to 2} f(x) = 4$, even though $f(2)$ is undefined!

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Key Insight:}} The limit exists and equals 4, but the function has a "hole" at $x = 2$.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Consider the piecewise function:
\[
f(x) = \begin{cases}
x + 2, & x \leq -1 \\
c + 2, & x > -1
\end{cases}
\]

Find the value of $c$ so that $\displaystyle\lim_{x \to -1} f(x)$ exists.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

For the limit to exist at $x = -1$, we need:
\[
\lim_{x \to -1^-} f(x) = \lim_{x \to -1^+} f(x)
\]

\textbf{Step 1:} Find the left-hand limit

As $x$ approaches $-1$ from the left, we use the first piece: $f(x) = x + 2$
\begin{align*}
\lim_{x \to -1^-} f(x) &= \lim_{x \to -1^-} (x + 2) \\
&= -1 + 2 \\
&= 1
\end{align*}

\textbf{Step 2:} Find the right-hand limit

As $x$ approaches $-1$ from the right, we use the second piece: $f(x) = c + 2$
\begin{align*}
\lim_{x \to -1^+} f(x) &= \lim_{x \to -1^+} (c + 2) \\
&= c + 2
\end{align*}

\textbf{Step 3:} Set them equal

For the limit to exist:
\begin{align*}
\lim_{x \to -1^-} f(x) &= \lim_{x \to -1^+} f(x) \\
1 &= c + 2 \\
c &= -1
\end{align*}

\textbf{Answer:} \boxed{c = -1}

\textbf{Verification:} With $c = -1$:
\begin{itemize}
    \item $\displaystyle\lim_{x \to -1^-} f(x) = 1$
    \item $\displaystyle\lim_{x \to -1^+} f(x) = -1 + 2 = 1$
    \item Both equal, so $\displaystyle\lim_{x \to -1} f(x) = 1$ exists! \textcolor{green}{\checkmark}
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate the following limits:

(a) $\displaystyle\lim_{x \to 3} (2x + 5)$

(b) $\displaystyle\lim_{x \to -2} (x^2 - 3x + 1)$

(c) $\displaystyle\lim_{x \to 1} \frac{x^2 + x - 2}{x^2 - x}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} For $\displaystyle\lim_{x \to 3} (2x + 5)$:

This is a polynomial, so we can substitute directly:
\begin{align*}
\lim_{x \to 3} (2x + 5) &= 2(3) + 5 \\
&= 6 + 5 \\
&= 11
\end{align*}

\textbf{Answer:} \boxed{11}

\vspace{0.3cm}
\textbf{(b)} For $\displaystyle\lim_{x \to -2} (x^2 - 3x + 1)$:

Again, polynomial, so direct substitution:
\begin{align*}
\lim_{x \to -2} (x^2 - 3x + 1) &= (-2)^2 - 3(-2) + 1 \\
&= 4 + 6 + 1 \\
&= 11
\end{align*}

\textbf{Answer:} \boxed{11}

\vspace{0.3cm}
\textbf{(c)} For $\displaystyle\lim_{x \to 1} \frac{x^2 + x - 2}{x^2 - x}$:

First try direct substitution:
\[
\frac{1^2 + 1 - 2}{1^2 - 1} = \frac{0}{0}
\]

This is indeterminate! We need to simplify first.

Factor numerator and denominator:
\begin{align*}
\text{Numerator: } x^2 + x - 2 &= (x + 2)(x - 1) \\
\text{Denominator: } x^2 - x &= x(x - 1)
\end{align*}

So:
\begin{align*}
\lim_{x \to 1} \frac{x^2 + x - 2}{x^2 - x} &= \lim_{x \to 1} \frac{(x+2)(x-1)}{x(x-1)} \\
&= \lim_{x \to 1} \frac{x+2}{x} \quad \text{(cancel } x-1 \text{, valid for } x \neq 1\text{)} \\
&= \frac{1+2}{1} \\
&= 3
\end{align*}

\textbf{Answer:} \boxed{3}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Strategy:}} When you get $\frac{0}{0}$, factor and cancel common terms!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Given that $\displaystyle\lim_{x \to 2} f(x) = 5$ and $\displaystyle\lim_{x \to 2} g(x) = -3$, find:

(a) $\displaystyle\lim_{x \to 2} [f(x) + 2g(x)]$

(b) $\displaystyle\lim_{x \to 2} [f(x) \cdot g(x)]$

(c) $\displaystyle\lim_{x \to 2} \frac{f(x)}{g(x) + 5}$

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{(a)} Using Sum Rule and Constant Multiple Rule:
\begin{align*}
\lim_{x \to 2} [f(x) + 2g(x)] &= \lim_{x \to 2} f(x) + \lim_{x \to 2} [2g(x)] \\
&= \lim_{x \to 2} f(x) + 2 \lim_{x \to 2} g(x) \\
&= 5 + 2(-3) \\
&= 5 - 6 \\
&= -1
\end{align*}

\textbf{Answer:} \boxed{-1}

\vspace{0.3cm}
\textbf{(b)} Using Product Rule:
\begin{align*}
\lim_{x \to 2} [f(x) \cdot g(x)] &= \left[\lim_{x \to 2} f(x)\right] \cdot \left[\lim_{x \to 2} g(x)\right] \\
&= 5 \cdot (-3) \\
&= -15
\end{align*}

\textbf{Answer:} \boxed{-15}

\vspace{0.3cm}
\textbf{(c)} Using Quotient Rule:

First find the limit of the denominator:
\begin{align*}
\lim_{x \to 2} [g(x) + 5] &= \lim_{x \to 2} g(x) + 5 \\
&= -3 + 5 \\
&= 2 \neq 0 \quad \textcolor{green}{\checkmark}
\end{align*}

Now apply quotient rule:
\begin{align*}
\lim_{x \to 2} \frac{f(x)}{g(x) + 5} &= \frac{\displaystyle\lim_{x \to 2} f(x)}{\displaystyle\lim_{x \to 2} [g(x) + 5]} \\
&= \frac{5}{2}
\end{align*}

\textbf{Answer:} \boxed{\frac{5}{2}}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to -3} \sqrt{\frac{x+2}{x+1}}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Check if direct substitution works

First verify the expression is defined at $x = -3$:
\[
\frac{-3+2}{-3+1} = \frac{-1}{-2} = \frac{1}{2} > 0 \quad \textcolor{green}{\checkmark}
\]

Since we're taking square root of a positive number, we can proceed.

\textbf{Step 2:} Apply limit laws

Using the composition property (limit of square root equals square root of limit):
\begin{align*}
\lim_{x \to -3} \sqrt{\frac{x+2}{x+1}} &= \sqrt{\lim_{x \to -3} \frac{x+2}{x+1}} \\
&= \sqrt{\frac{\displaystyle\lim_{x \to -3} (x+2)}{\displaystyle\lim_{x \to -3} (x+1)}} \quad \text{(quotient rule)} \\
&= \sqrt{\frac{-3+2}{-3+1}} \\
&= \sqrt{\frac{-1}{-2}} \\
&= \sqrt{\frac{1}{2}} \\
&= \frac{1}{\sqrt{2}} \\
&= \frac{\sqrt{2}}{2}
\end{align*}

\textbf{Answer:} \boxed{\frac{\sqrt{2}}{2}}

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 1.2 Summary}}

\begin{center}
\begin{tabular}{|p{6cm}|p{8cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Concept} & \textbf{Meaning} \\
\hline
$\displaystyle\lim_{x \to a} f(x) = L$ & $f(x)$ approaches $L$ as $x$ approaches $a$ \\
\hline
Limit vs Function Value & $\displaystyle\lim_{x \to a} f(x)$ can exist even if $f(a)$ doesn't! \\
\hline
One-Sided Limits & Left: $x \to a^-$ ; Right: $x \to a^+$ \\
\hline
Limit Existence & Limit exists $\iff$ both one-sided limits exist and are equal \\
\hline
Direct Substitution & Works for polynomials and continuous functions \\
\hline
Indeterminate Form $\frac{0}{0}$ & Factor and cancel, then try again \\
\hline
\end{tabular}
\end{center}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Problem-Solving Strategy:}}
\begin{enumerate}
    \item Try direct substitution first
    \item If you get a number (not $\frac{0}{0}$), that's your answer
    \item If you get $\frac{0}{0}$, factor numerator and denominator
    \item Cancel common factors and try substitution again
    \item For piecewise functions, check one-sided limits separately
\end{enumerate}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Common Mistakes to Avoid:}}
\begin{itemize}
    \item Confusing $\displaystyle\lim_{x \to a} f(x)$ with $f(a)$
    \item Forgetting to check both one-sided limits for piecewise functions
    \item Canceling terms incorrectly when dealing with $\frac{0}{0}$
    \item Dividing by zero in quotient rule (denominator limit must be non-zero!)
\end{itemize}

\newpage

When evaluating $\displaystyle\lim_{x \to a} f(x)$, use these techniques in order:

\textbf{Technique 1: Direct Substitution}
\begin{itemize}
    \item If $f$ is continuous at $a$, then $\displaystyle\lim_{x \to a} f(x) = f(a)$
    \item Works for polynomials, rational functions (where denominator $\neq 0$)
\end{itemize}

\textbf{Technique 2: Factoring and Canceling}
\begin{itemize}
    \item Used when direct substitution gives $\frac{0}{0}$
    \item Factor both numerator and denominator
    \item Cancel common factors
    \item Try direct substitution again
\end{itemize}

\textbf{Technique 3: Rationalization}
\begin{itemize}
    \item Used when square roots appear in numerator or denominator
    \item Multiply by conjugate: $(a - b)(a + b) = a^2 - b^2$
\end{itemize}

\textbf{Technique 4: Common Denominator}
\begin{itemize}
    \item Used for complex fractions
    \item Combine fractions with LCD
    \item Simplify and apply other techniques
\end{itemize}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to 2} \frac{4x - x^2}{2 - \sqrt{x}}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Try direct substitution
\[
\frac{4(2) - 2^2}{2 - \sqrt{2}} = \frac{8 - 4}{2 - \sqrt{2}} = \frac{4}{2 - \sqrt{2}}
\]

This is defined (not $\frac{0}{0}$), so we can compute:
\[
\frac{4}{2 - \sqrt{2}} = \frac{4}{2 - 1.414...} \approx \frac{4}{0.586} \approx 6.83
\]

But let's rationalize the denominator for an exact answer.

\textbf{Step 2:} Rationalize the denominator

Multiply numerator and denominator by the conjugate $(2 + \sqrt{x})$:
\begin{align*}
\lim_{x \to 2} \frac{4x - x^2}{2 - \sqrt{x}} &= \lim_{x \to 2} \frac{4x - x^2}{2 - \sqrt{x}} \cdot \frac{2 + \sqrt{x}}{2 + \sqrt{x}} \\
&= \lim_{x \to 2} \frac{(4x - x^2)(2 + \sqrt{x})}{(2 - \sqrt{x})(2 + \sqrt{x})} \\
&= \lim_{x \to 2} \frac{(4x - x^2)(2 + \sqrt{x})}{4 - x}
\end{align*}

\textbf{Step 3:} Factor the numerator

Factor $4x - x^2 = x(4 - x) = -x(x - 4)$:
\begin{align*}
&= \lim_{x \to 2} \frac{-x(x-4)(2 + \sqrt{x})}{4 - x} \\
&= \lim_{x \to 2} \frac{-x(x-4)(2 + \sqrt{x})}{-(x-4)} \\
&= \lim_{x \to 2} \frac{x(x-4)(2 + \sqrt{x})}{x-4} \\
&= \lim_{x \to 2} x(2 + \sqrt{x}) \quad \text{(cancel } x-4\text{)}
\end{align*}

\textbf{Step 4:} Apply direct substitution
\begin{align*}
&= 2(2 + \sqrt{2}) \\
&= 4 + 2\sqrt{2}
\end{align*}

\textbf{Answer:} \boxed{4 + 2\sqrt{2}}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Verification:}} $4 + 2\sqrt{2} \approx 4 + 2(1.414) = 6.828$ \textcolor{green}{\checkmark} matches our estimate!

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to 5} \frac{4 - x}{\sqrt{x+4} - \sqrt{x-4}}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Try direct substitution
\[
\frac{4 - 5}{\sqrt{5+4} - \sqrt{5-4}} = \frac{-1}{\sqrt{9} - \sqrt{1}} = \frac{-1}{3 - 1} = \frac{-1}{2}
\]

This works! But let's verify using algebraic manipulation.

\textbf{Alternative Method - Rationalization:}

Multiply by conjugate of denominator: $(\sqrt{x+4} + \sqrt{x-4})$

\begin{align*}
&= \lim_{x \to 5} \frac{4-x}{\sqrt{x+4} - \sqrt{x-4}} \cdot \frac{\sqrt{x+4} + \sqrt{x-4}}{\sqrt{x+4} + \sqrt{x-4}} \\
&= \lim_{x \to 5} \frac{(4-x)(\sqrt{x+4} + \sqrt{x-4})}{(\sqrt{x+4})^2 - (\sqrt{x-4})^2} \\
&= \lim_{x \to 5} \frac{(4-x)(\sqrt{x+4} + \sqrt{x-4})}{(x+4) - (x-4)} \\
&= \lim_{x \to 5} \frac{(4-x)(\sqrt{x+4} + \sqrt{x-4})}{8} \\
&= \frac{1}{8} \lim_{x \to 5} (4-x)(\sqrt{x+4} + \sqrt{x-4})
\end{align*}

\textbf{Step 2:} Substitute $x = 5$
\begin{align*}
&= \frac{1}{8} (4-5)(\sqrt{5+4} + \sqrt{5-4}) \\
&= \frac{1}{8} (-1)(\sqrt{9} + \sqrt{1}) \\
&= \frac{1}{8} (-1)(3 + 1) \\
&= \frac{-4}{8} \\
&= -\frac{1}{2}
\end{align*}

\textbf{Answer:} \boxed{-\frac{1}{2}}

Both methods agree! \textcolor{green}{\checkmark}

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to 9} \frac{\sqrt{x} - 3}{x - 9}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Try direct substitution
\[
\frac{\sqrt{9} - 3}{9 - 9} = \frac{3 - 3}{0} = \frac{0}{0}
\]

Indeterminate form! Need to simplify.

\textbf{Step 2:} Rationalize the numerator

Multiply by conjugate $(\sqrt{x} + 3)$:
\begin{align*}
\lim_{x \to 9} \frac{\sqrt{x} - 3}{x - 9} &= \lim_{x \to 9} \frac{\sqrt{x} - 3}{x - 9} \cdot \frac{\sqrt{x} + 3}{\sqrt{x} + 3} \\
&= \lim_{x \to 9} \frac{(\sqrt{x})^2 - 3^2}{(x-9)(\sqrt{x} + 3)} \\
&= \lim_{x \to 9} \frac{x - 9}{(x-9)(\sqrt{x} + 3)}
\end{align*}

\textbf{Step 3:} Cancel common factor $(x - 9)$
\begin{align*}
&= \lim_{x \to 9} \frac{1}{\sqrt{x} + 3}
\end{align*}

\textbf{Step 4:} Apply direct substitution
\begin{align*}
&= \frac{1}{\sqrt{9} + 3} \\
&= \frac{1}{3 + 3} \\
&= \frac{1}{6}
\end{align*}

\textbf{Answer:} \boxed{\frac{1}{6}}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Key Pattern:}} When you see $\sqrt{x} - a$ in numerator and $x - a^2$ in denominator, rationalize!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{h \to 0} \frac{\frac{1}{x+h} - \frac{1}{x}}{h}
\]

(This is the derivative of $\frac{1}{x}$ from first principles!)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Simplify the complex fraction

Find common denominator for the numerator:
\begin{align*}
\frac{1}{x+h} - \frac{1}{x} &= \frac{x}{x(x+h)} - \frac{x+h}{x(x+h)} \\
&= \frac{x - (x+h)}{x(x+h)} \\
&= \frac{x - x - h}{x(x+h)} \\
&= \frac{-h}{x(x+h)}
\end{align*}

\textbf{Step 2:} Substitute back into the limit
\begin{align*}
\lim_{h \to 0} \frac{\frac{1}{x+h} - \frac{1}{x}}{h} &= \lim_{h \to 0} \frac{\frac{-h}{x(x+h)}}{h} \\
&= \lim_{h \to 0} \frac{-h}{x(x+h)} \cdot \frac{1}{h} \\
&= \lim_{h \to 0} \frac{-h}{hx(x+h)} \\
&= \lim_{h \to 0} \frac{-1}{x(x+h)} \quad \text{(cancel } h\text{)}
\end{align*}

\textbf{Step 3:} Apply direct substitution
\begin{align*}
&= \frac{-1}{x(x+0)} \\
&= \frac{-1}{x^2} \\
&= -\frac{1}{x^2}
\end{align*}

\textbf{Answer:} \boxed{-\frac{1}{x^2}}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Insight:}} This confirms that $\frac{d}{dx}\left(\frac{1}{x}\right) = -\frac{1}{x^2}$!

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to 2} \frac{x^3 + 2x - 12}{5 - x}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Try direct substitution
\begin{align*}
\frac{2^3 + 2(2) - 12}{5 - 2} &= \frac{8 + 4 - 12}{3} \\
&= \frac{0}{3} \\
&= 0
\end{align*}

This is well-defined (not $\frac{0}{0}$)!

\textbf{Answer:} \boxed{0}

\textcolor{green}{\textbf{Verification:}} The numerator equals zero at $x = 2$, but the denominator does not, so the limit is simply 0.

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} Not every limit requires complex algebra! Always try direct substitution first.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to 3^+} \frac{x + 1}{x - 3}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Analyze numerator and denominator at $x = 3$

Numerator: $3 + 1 = 4 \neq 0$

Denominator: $3 - 3 = 0$

This suggests an infinite limit.

\textbf{Step 2:} Determine the sign

Since we approach from the right ($x \to 3^+$), we have $x > 3$, so:
\begin{itemize}
    \item $x + 1 > 0$ (always positive near 3)
    \item $x - 3 > 0$ (positive when $x > 3$)
\end{itemize}

\textbf{Step 3:} Create a table approaching from the right

\begin{center}
\begin{tabular}{|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$x$ & $x - 3$ & $\frac{x+1}{x-3}$ \\
\hline
3.1 & 0.1 & $\frac{4.1}{0.1} = 41$ \\
\hline
3.01 & 0.01 & $\frac{4.01}{0.01} = 401$ \\
\hline
3.001 & 0.001 & $\frac{4.001}{0.001} = 4001$ \\
\hline
\end{tabular}
\end{center}

\textcolor{green}{\textbf{Conclusion:}} As $x \to 3^+$, the fraction grows without bound.

\textbf{Answer:} \boxed{\lim_{x \to 3^+} \frac{x+1}{x-3} = +\infty}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} From the left ($x \to 3^-$), we would get $-\infty$ because $x - 3 < 0$.

\vspace{0.5cm}

\textcolor{primaryblue}{\faCheckCircle\ \textbf{Section 1.3 Summary}}

\begin{center}
\begin{tabular}{|p{5cm}|p{9cm}|}
\hline
\rowcolor{primaryblue!20}
\textbf{Technique} & \textbf{When to Use} \\
\hline
Direct Substitution & First attempt; works when function is continuous \\
\hline
Factoring & When you get $\frac{0}{0}$; factor and cancel common terms \\
\hline
Rationalization & Square roots in numerator or denominator; multiply by conjugate \\
\hline
Common Denominator & Complex fractions; combine fractions first \\
\hline
Infinite Limits & Numerator $\neq 0$, denominator $= 0$; limit is $\pm\infty$ \\
\hline
\end{tabular}
\end{center}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Problem-Solving Flowchart:}}
\begin{enumerate}
    \item \textbf{Try direct substitution}
    \begin{itemize}
        \item If you get a number $\to$ that's your answer
        \item If you get $\frac{\text{nonzero}}{0} \to$ infinite limit
        \item If you get $\frac{0}{0} \to$ continue to step 2
    \end{itemize}
    \item \textbf{Simplify algebraically}
    \begin{itemize}
        \item Factor if polynomial
        \item Rationalize if square roots present
        \item Find common denominator if complex fraction
    \end{itemize}
    \item \textbf{Cancel common factors}
    \item \textbf{Try direct substitution again}
\end{enumerate}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Key Formulas to Remember:}}
\begin{itemize}
    \item Conjugate: $(a - b)(a + b) = a^2 - b^2$
    \item Difference of squares: $x^2 - a^2 = (x-a)(x+a)$
    \item Factoring: $x^2 + bx + c = (x + p)(x + q)$ where $p + q = b$, $pq = c$
\end{itemize}

