\textcolor{primaryblue}{\textbf{Problem:}} Solve:
\[
\frac{5}{4}e^x = \frac{1}{4}\sinh x
\]

(This is from 2023 past paper, Q1 part iii)

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Recall definition of $\sinh x$
\[
\sinh x = \frac{e^x - e^{-x}}{2}
\]

\textbf{Step 2:} Substitute into the equation
\begin{align*}
\frac{5}{4}e^x &= \frac{1}{4} \cdot \frac{e^x - e^{-x}}{2} \\
\frac{5}{4}e^x &= \frac{e^x - e^{-x}}{8}
\end{align*}

\textbf{Step 3:} Multiply both sides by 8
\[
10e^x = e^x - e^{-x}
\]

\textbf{Step 4:} Rearrange
\begin{align*}
10e^x - e^x &= -e^{-x} \\
9e^x &= -e^{-x}
\end{align*}

\textbf{Step 5:} Multiply both sides by $e^x$
\begin{align*}
9e^{2x} &= -1 \\
e^{2x} &= -\frac{1}{9}
\end{align*}

\textcolor{red}{\textbf{Conclusion:}} Since $e^{2x} > 0$ for all real $x$, but the right side is negative, there is \textbf{no real solution}.

\textbf{Answer:} \boxed{\text{No solution in } \mathbb{R}}

\textcolor{accentorange}{\faExclamationTriangle\ \textbf{Note:}} This equation has no real solution because the exponential function is always positive.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to \infty} \frac{3x^2 - 5x + 2}{2x^2 + x - 1}
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Method 1: Divide by highest power}

The highest power in the denominator is $x^2$. Divide every term by $x^2$:
\begin{align*}
\lim_{x \to \infty} \frac{3x^2 - 5x + 2}{2x^2 + x - 1} &= \lim_{x \to \infty} \frac{\frac{3x^2}{x^2} - \frac{5x}{x^2} + \frac{2}{x^2}}{\frac{2x^2}{x^2} + \frac{x}{x^2} - \frac{1}{x^2}} \\
&= \lim_{x \to \infty} \frac{3 - \frac{5}{x} + \frac{2}{x^2}}{2 + \frac{1}{x} - \frac{1}{x^2}}
\end{align*}

\textbf{Step 2:} Apply limit (as $x \to \infty$, terms with $x$ in denominator go to 0)
\begin{align*}
&= \frac{3 - 0 + 0}{2 + 0 - 0} \\
&= \frac{3}{2}
\end{align*}

\textbf{Method 2: Quick rule}

Since degrees are equal (both degree 2), the limit is the ratio of leading coefficients:
\[
\frac{3}{2}
\]

\textbf{Answer:} \boxed{\frac{3}{2}}

\textcolor{primaryblue}{\faLightbulb\ \textbf{Horizontal Asymptote:}} The line $y = \frac{3}{2}$ is a horizontal asymptote.

\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{Problem:}} Evaluate:
\[
\lim_{x \to \infty} \left(\sqrt{x^2 + 4x} - x\right)
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\textbf{Step 1:} Check the form

As $x \to \infty$: $\sqrt{x^2 + 4x} \to \infty$ and $x \to \infty$

So we have the form $\infty - \infty$ (indeterminate).

\textbf{Step 2:} Rationalize by multiplying by conjugate
\begin{align*}
&\lim_{x \to \infty} \left(\sqrt{x^2 + 4x} - x\right) \cdot \frac{\sqrt{x^2 + 4x} + x}{\sqrt{x^2 + 4x} + x} \\
&= \lim_{x \to \infty} \frac{(\sqrt{x^2 + 4x})^2 - x^2}{\sqrt{x^2 + 4x} + x} \\
&= \lim_{x \to \infty} \frac{x^2 + 4x - x^2}{\sqrt{x^2 + 4x} + x} \\
&= \lim_{x \to \infty} \frac{4x}{\sqrt{x^2 + 4x} + x}
\end{align*}

\textbf{Step 3:} Divide numerator and denominator by $x$

For the square root term: $\sqrt{x^2 + 4x} = \sqrt{x^2(1 + \frac{4}{x})} = x\sqrt{1 + \frac{4}{x}}$ (assuming $x > 0$)

\begin{align*}
&= \lim_{x \to \infty} \frac{4x}{x\sqrt{1 + \frac{4}{x}} + x} \\
&= \lim_{x \to \infty} \frac{4x}{x\left(\sqrt{1 + \frac{4}{x}} + 1\right)} \\
&= \lim_{x \to \infty} \frac{4}{\sqrt{1 + \frac{4}{x}} + 1}
\end{align*}

\textbf{Step 4:} Apply the limit
\begin{align*}
&= \frac{4}{\sqrt{1 + 0} + 1} \\
&= \frac{4}{1 + 1} \\
&= \frac{4}{2} \\
&= 2
\end{align*}

\textbf{Answer:} \boxed{2}

\textcolor{green}{\textbf{Interpretation:}} Even though both terms go to infinity, their difference approaches 2.

